<?php
/**
 * Plugin Name: NESPORTS3 Updater V29 (Remove Login & Direct Payment Method Checkout)
 * Description: Completely removes login option from the website and redirects Add to Cart directly to the payment method checkout page.
 * Version: 29.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v29_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (strpos($f, 'nesports-pro') === 0) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }
    
    $payloads = array(
        'templates/header-nesports.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'templates/page-product.php' => base64_decode(''),
        'templates/page-checkout.php' => base64_decode(''),
        'includes/class-nesports-frontend.php' => base64_decode(''),
        'assets/js/nesports-frontend.js' => base64_decode(''),
        'assets/css/nesports-frontend.css' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v29']) && $_GET['nesports_apply_v29'] === '1') {
        $res = run_nesports_v29_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_v29_update();
});
